export interface ConnectorConfig {
  /** Pusher Channels app key (from Pusher dashboard) */
  pusherAppKey: string
  /** Pusher Channels app secret (from Pusher dashboard) */
  pusherSecret: string
  /** Pusher Channels cluster identifier (e.g., 'mt1', 'eu', 'ap1') */
  pusherCluster: string
  /** Optional pre-computed Authorization token. If omitted, a signed token is generated. */
  pusherAuthToken?: string
  /** Injected fetch implementation for testing. Defaults to global fetch. */
  fetch?: typeof fetch
}

export interface ZendeskTicketUpdatedPayload {
  type: string
  account_id: number
  id: string
  time: string
  zendesk_event_version: string
  subject: string
  detail: {
    id: string
    status: string
    subject: string
    latest_comment?: {
      body: string
    }
  }
  event: Record<string, unknown>
}

export interface HandleResult {
  channel: string
  eventName: string
  eventData: {
    subject: string
    latest_comment?: string
  }
  pusherResponse: unknown
}

function generatePusherAuthToken(
  appKey: string,
  secret: string,
  method: string,
  path: string,
  body: string
): string {
  const timestamp = Math.floor(Date.now() / 1000).toString()
  const bodyMd5 = cryptoHash(body)
  const queryParams = new URLSearchParams({
    auth_key: appKey,
    auth_timestamp: timestamp,
    auth_version: '1.0',
    body_md5: bodyMd5,
  })
  const sortedQuery = Array.from(queryParams.entries())
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}=${v}`)
    .join('&')
  const stringToSign = `${method}\n${path}\n${sortedQuery}`
  const signature = hmacSha256(secret, stringToSign)
  return `Bearer ${appKey}:${signature}`
}

async function cryptoHash(input: string): Promise<string> {
  const encoder = new TextEncoder()
  const data = encoder.encode(input)
  const hashBuffer = await crypto.subtle.digest('MD5', data)
  const hashArray = Array.from(new Uint8Array(hashBuffer))
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('')
}

async function hmacSha256(secret: string, message: string): Promise<string> {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(message))
  const sigArray = Array.from(new Uint8Array(signature))
  return sigArray.map((b) => b.toString(16).padStart(2, '0')).join('')
}

export async function handle(
  payload: ZendeskTicketUpdatedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id (ticket ID)')
  }
  if (!payload.detail?.status) {
    throw new Error('Missing required field: detail.status (ticket status)')
  }
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject (ticket subject)')
  }

  const ticketId = payload.detail.id
  const channel = `presence-ticket-${ticketId}`
  const eventName = 'ticket.updated'
  const eventData: HandleResult['eventData'] = {
    subject: payload.detail.subject,
  }
  if (payload.detail.latest_comment?.body) {
    eventData.latest_comment = payload.detail.latest_comment.body
  }

  const bodyObj = { name: eventName, channel, data: eventData }
  const body = JSON.stringify(bodyObj)

  const path = `/apps/${config.pusherAppKey}/channels/${channel}/events`
  const url = `https://ws-${config.pusherCluster}.pusher.com${path}`

  let authToken: string
  if (config.pusherAuthToken) {
    authToken = config.pusherAuthToken
  } else {
    authToken = await generatePusherAuthToken(config.pusherAppKey, config.pusherSecret, 'POST', path, body)
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: authToken,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Pusher Channels API error: ${response.status} ${response.statusText} at POST ${url}`)
  }

  const pusherResponse = (await response.json()) as unknown

  return {
    channel,
    eventName,
    eventData,
    pusherResponse,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketUpdatedPayload, HandleResult } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pusherAppKey: 'test-app-key',
      pusherSecret: 'test-secret',
      pusherCluster: 'mt1',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketUpdatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('presence-ticket-98765')
    expect(result.eventName).toBe('ticket.updated')
    expect(result.eventData.subject).toBe('Help needed with login')
    expect(result.eventData.latest_comment).toBe('I cannot access my account after password reset.')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let recordedCalls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      pusherAppKey: 'test-app-key',
      pusherSecret: 'test-secret',
      pusherCluster: 'mt1',
    }
    recordedCalls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response | Promise<Response>) {
    const { fetch, calls } = fakeFetch(handler)
    recordedCalls.push(...calls)
    return fetch
  }

  function makePayload(overrides: Partial<ZendeskTicketUpdatedPayload> = {}): ZendeskTicketUpdatedPayload {
    return {
      type: 'zen:event-type:ticket.updated',
      account_id: 123456,
      id: 'abc123-def456-ghi789',
      time: '2024-01-15T10:30:00Z',
      zendesk_event_version: '2022-06-20',
      subject: 'zen:ticket:98765',
      detail: {
        id: '98765',
        status: 'open',
        subject: 'Help needed with login',
        latest_comment: {
          body: 'I cannot access my account after password reset.',
        },
      },
      event: {},
      ...overrides,
    }
  }

  it('happy path: sends correct request to Pusher with signed auth', async () => {
    const fetch = makeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://ws-mt1.pusher.com/apps/test-app-key/channels/presence-ticket-98765/events')
      expect(req.headers.get('content-type')).toBe('application/json')
      expect(req.headers.get('authorization')).toMatch(/^Bearer test-app-key:[a-f0-9]{64}$/)
      const body = req.json as { name: string; channel: string; data: { subject: string; latest_comment: string } }
      expect(body.name).toBe('ticket.updated')
      expect(body.channel).toBe('presence-ticket-98765')
      expect(body.data.subject).toBe('Help needed with login')
      expect(body.data.latest_comment).toBe('I cannot access my account after password reset.')
      return jsonResponse({}, 200)
    })

    const result = await handle(makePayload(), { ...baseConfig, fetch })
    expect(result.channel).toBe('presence-ticket-98765')
    expect(result.eventName).toBe('ticket.updated')
    expect(result.eventData.subject).toBe('Help needed with login')
    expect(result.eventData.latest_comment).toBe('I cannot access my account after password reset.')
  })

  it('uses pre-computed auth token when provided', async () => {
    const fetch = makeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer precomputed-token')
      return jsonResponse({}, 200)
    })

    const config: ConnectorConfig = { ...baseConfig, pusherAuthToken: 'Bearer precomputed-token', fetch }
    await handle(makePayload(), config)
  })

  it('omits latest_comment from event data when not present in payload', async () => {
    const fetch = makeFetch((req) => {
      const body = req.json as { data: { subject: string; latest_comment?: string } }
      expect(body.data.subject).toBe('Help needed with login')
      expect(body.data.latest_comment).toBeUndefined()
      return jsonResponse({}, 200)
    })

    const payload = makePayload({ detail: { ...makePayload().detail, latest_comment: undefined } })
    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.eventData.latest_comment).toBeUndefined()
  })

  it('throws descriptive error when detail.id is missing', async () => {
    const payload = makePayload({ detail: { ...makePayload().detail, id: '' } })
    await expect(handle(payload, { ...baseConfig, fetch: makeFetch(() => jsonResponse({}, 200)) })).rejects.toThrow(
      'Missing required field: detail.id (ticket ID)'
    )
  })

  it('throws descriptive error when detail.status is missing', async () => {
    const payload = makePayload({ detail: { ...makePayload().detail, status: '' } })
    await expect(handle(payload, { ...baseConfig, fetch: makeFetch(() => jsonResponse({}, 200)) })).rejects.toThrow(
      'Missing required field: detail.status (ticket status)'
    )
  })

  it('throws descriptive error when detail.subject is missing', async () => {
    const payload = makePayload({ detail: { ...makePayload().detail, subject: '' } })
    await expect(handle(payload, { ...baseConfig, fetch: makeFetch(() => jsonResponse({}, 200)) })).rejects.toThrow(
      'Missing required field: detail.subject (ticket subject)'
    )
  })

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const fetch = makeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(makePayload(), { ...baseConfig, fetch })).rejects.toThrow(
      'Pusher Channels API error: 401 Unauthorized at POST https://ws-mt1.pusher.com/apps/test-app-key/channels/presence-ticket-98765/events'
    )
  })

  it('throws error with status code and endpoint on 5xx response', async () => {
    const fetch = makeFetch(() => jsonResponse({ error: 'Internal Server Error' }, 500))
    await expect(handle(makePayload(), { ...baseConfig, fetch })).rejects.toThrow(
      'Pusher Channels API error: 500 Internal Server Error at POST https://ws-mt1.pusher.com/apps/test-app-key/channels/presence-ticket-98765/events'
    )
  })

  it('constructs channel name with presence-ticket- prefix', async () => {
    const fetch = makeFetch((req) => {
      expect(req.url).toContain('/channels/presence-ticket-98765/events')
      return jsonResponse({}, 200)
    })
    await handle(makePayload(), { ...baseConfig, fetch })
  })

  it('hardcodes event name to ticket.updated regardless of ticket status', async () => {
    const fetch = makeFetch((req) => {
      const body = req.json as { name: string }
      expect(body.name).toBe('ticket.updated')
      return jsonResponse({}, 200)
    })
    const payload = makePayload({ detail: { ...makePayload().detail, status: 'closed' } })
    await handle(payload, { ...baseConfig, fetch })
  })

  it('includes ticket subject in event data', async () => {
    const fetch = makeFetch((req) => {
      const body = req.json as { data: { subject: string } }
      expect(body.data.subject).toBe('Custom subject text')
      return jsonResponse({}, 200)
    })
    const payload = makePayload({ detail: { ...makePayload().detail, subject: 'Custom subject text' } })
    await handle(payload, { ...baseConfig, fetch })
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developer.zendesk.com/api-reference/webhooks/event-types/webhook-event-types
